{% set currency = frappe.db.get_value('Currency', doc.currency, 'symbol') or doc.currency or 'YER' %}
{% set company = frappe.get_doc('Company', doc.company) %}
{% set branding_logo = frappe.db.get_single_value('POS Branding Settings', 'primary_logo') if frappe.db.exists('DocType', 'POS Branding Settings') else '' %}
{% set logo = company.company_logo or branding_logo or '' %}
{% set issue_time = (doc.posting_time|string).split('.')[0] if doc.posting_time else '' %}
{% set outstanding = doc.outstanding_amount or 0 %}
{% set customer_debt = frappe.db.sql("select coalesce(sum(outstanding_amount), 0) from `tabSales Invoice` where customer=%s and company=%s and docstatus=1", (doc.customer, doc.company))[0][0] if doc.customer else 0 %}
<style>
@font-face{font-family:CairoPOS;src:url('/assets/pos_next/fonts/Cairo-Variable.ttf') format('truetype');font-weight:200 1000;}@page{size:80mm auto;margin:0}*{box-sizing:border-box}body{color:#172033;font-family:CairoPOS,'DejaVu Sans',sans-serif;font-size:10px;line-height:1.62;margin:0 auto;padding:7px 8px 14px;width:80mm}.center{text-align:center}.brand{border-bottom:2px solid #0f766e;padding:2px 0 8px}.logo{display:block;max-height:52px;max-width:118px;margin:0 auto 5px;object-fit:contain}.brand h1{font-size:17px;line-height:1.25;margin:0}.brand small{color:#526575;font-size:8px}.type{background:#ecfdf5;border:1px solid #99f6e4;border-radius:12px;color:#075e54;display:inline-block;font-size:8px;font-weight:800;margin-top:6px;padding:2px 10px}.status{border-radius:9px;display:inline-block;font-size:8px;font-weight:800;margin-top:4px;padding:2px 9px}.paid{background:#dcfce7;color:#166534}.due{background:#fee2e2;color:#b91c1c}.rule{border:0;border-top:1px dashed #b8c6cd;margin:8px 0}.row{display:flex;gap:8px;justify-content:space-between;padding:2px 0}.label{color:#64748b;white-space:nowrap}.value{direction:ltr;font-weight:800;text-align:left}.customer{background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;margin:8px 0;padding:7px}.customer strong{display:block;font-size:11px}.debt{background:#fff1f2;border:1px solid #fecdd3;border-radius:8px;color:#9f1239;margin:8px 0;padding:7px}.debt strong{display:block;direction:ltr;font-size:14px;margin-top:2px}.debt small{color:#9f1239;display:block;font-size:8px}.head{color:#64748b;display:flex;font-size:8px;justify-content:space-between;margin-bottom:4px}.item{border-top:1px solid #e7eef0;padding:7px 0}.item-name{font-size:10px;font-weight:800}.item-info{color:#526575;display:flex;font-size:8.5px;justify-content:space-between;margin-top:2px}.serial{color:#0f766e;direction:ltr;font-family:monospace;font-size:8px;margin-top:2px}.summary{border-top:2px solid #0f766e;margin-top:6px;padding-top:5px}.total{background:#ecfdf5;border:1px solid #a7f3d0;border-radius:8px;color:#065f46;font-size:13px;font-weight:900;margin-top:6px;padding:7px}.payment{background:#f8fafc;border-radius:7px;margin-top:7px;padding:6px}.footer{border-top:1px dashed #b8c6cd;color:#64748b;font-size:8px;margin-top:10px;padding-top:7px;text-align:center}.footer b{color:#075e54;display:block;font-size:11px}
</style>
<div class='center brand'>{% if logo %}<img class='logo' src='{{ logo }}' alt='{{ company.company_name or doc.company }}'>{% endif %}<h1>{{ company.company_name or doc.company }}</h1>{% if company.phone_no %}<small>{{ company.phone_no }}</small>{% endif %}<div class='type'>{% if doc.is_return %}إشعار مرتجع{% else %}فاتورة مبيعات{% endif %}</div><br><div class='status {% if outstanding > 0 %}due{% else %}paid{% endif %}'>{% if doc.is_return %}تم تسجيل المرتجع{% elif outstanding > 0 %}بيع آجل — يوجد مبلغ مستحق{% else %}مدفوعة بالكامل{% endif %}</div></div><div class='row'><span class='label'>رقم الفاتورة</span><span class='value'>{{ doc.name }}</span></div><div class='row'><span class='label'>التاريخ والوقت</span><span class='value'>{{ doc.posting_date }}{% if issue_time %} {{ issue_time }}{% endif %}</span></div><div class='customer'><span class='label'>العميل</span><strong>{{ doc.customer_name or doc.customer or 'عميل نقدي' }}</strong>{% if doc.contact_mobile %}<span class='value'>{{ doc.contact_mobile }}</span>{% endif %}</div>{% if outstanding > 0 %}<div class='debt'><span>الرصيد الإجمالي المستحق على العميل بعد هذه الفاتورة</span><strong>{{ '%.2f'|format(customer_debt) }} {{ currency }}</strong><small>يشمل هذه الفاتورة وأي فواتير آجلة سابقة.</small></div>{% endif %}<hr class='rule'><div class='head'><span>الصنف</span><span>الإجمالي</span></div>{% for item in doc.items %}<div class='item'><div class='row'><span class='item-name'>{{ item.item_name }}</span><span class='value'>{{ '%.2f'|format(item.amount or 0) }} {{ currency }}</span></div><div class='item-info'><span>{{ '%.2f'|format(item.qty or 0) }} {{ item.uom or '' }} × {{ '%.2f'|format(item.rate or 0) }}</span>{% if item.discount_amount %}<span>خصم {{ '%.2f'|format(item.discount_amount) }}</span>{% endif %}</div>{% if item.serial_no %}<div class='serial'>IMEI / S/N: {{ item.serial_no|replace('\n', ', ') }}</div>{% endif %}</div>{% endfor %}<section class='summary'><div class='row'><span class='label'>إجمالي الأصناف</span><span class='value'>{{ '%.2f'|format(doc.total or 0) }} {{ currency }}</span></div>{% if doc.discount_amount %}<div class='row'><span class='label'>خصم الفاتورة</span><span class='value'>- {{ '%.2f'|format(doc.discount_amount) }} {{ currency }}</span></div>{% endif %}<div class='row total'><span>الإجمالي المستحق</span><span class='value'>{{ '%.2f'|format(doc.grand_total or 0) }} {{ currency }}</span></div></section><div class='payment'><div class='row'><span class='label'>المدفوع الآن</span><span class='value'>{{ '%.2f'|format(doc.paid_amount or 0) }} {{ currency }}</span></div>{% if outstanding > 0 %}<div class='row'><span class='label'>متبقي هذه الفاتورة</span><span class='value'>{{ '%.2f'|format(outstanding) }} {{ currency }}</span></div>{% endif %}{% for payment in doc.payments if payment.amount %}<div class='row'><span class='label'>{{ payment.mode_of_payment }}</span><span class='value'>{{ '%.2f'|format(payment.amount) }} {{ currency }}</span></div>{% endfor %}</div><footer class='footer'><b>شكرًا لثقتكم بنا</b>احتفظ بهذه الفاتورة للرجوع إليها عند الحاجة.</footer>
